14	export class SceneTransitionRuntime {
15	  syncVeil(veil: TransitionVeilRuntimePort | null, progress: number): void {
16	    if (!veil) return;
17	    veil.setRuntimeState({
18	      active: true,
19	      progress: Helpers.clamp01(progress),
20	    });
21	  }
22	
23	  resetVeil(
24	    veil: TransitionVeilRuntimePort | null,
25	    inactiveProgress = DEFAULT_INACTIVE_PROGRESS,
26	  ): void {
27	    if (!veil) return;
28	    veil.setRuntimeState({
29	      active: false,
30	      progress: Helpers.clamp01(inactiveProgress),
31	    });
32	  }
33	
34	  async play(
35	    options: SceneTransitionPlayOptions,
36	    gsap: GsapGlobal | null,
37	  ): Promise<void> {
38	    const { veil, steps, onStepComplete, initialState, finalState } = options;
39	    if (!veil || steps.length === 0) {
40	      if (onStepComplete) await onStepComplete(0);
41	      return;
42	    }
43	
44	    veil.setRuntimeState({
45	      active: true,
46	      progress: Helpers.clamp01(initialState?.progress ?? steps[0]?.from ?? 0),
47	      ...initialState,
48	    });
49	
50	    if (!gsap) {
51	      for (let index = 0; index < steps.length; index += 1) {
52	        veil.setRuntimeState({
53	          active: true,
54	          progress: Helpers.clamp01(steps[index].to),
55	        });
56	        if (onStepComplete) await onStepComplete(index);
57	      }
58	      veil.setRuntimeState({
59	        active: false,
60	        progress: Helpers.clamp01(
61	          finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
62	        ),
63	        ...finalState,
64	      });
65	      return;
66	    }
67	
68	    for (let index = 0; index < steps.length; index += 1) {
69	      await this._playStep(gsap, veil, steps[index]);
70	      if (onStepComplete) await onStepComplete(index);
71	    }
72	
73	    veil.setRuntimeState({
74	      active: false,
75	      progress: Helpers.clamp01(
76	        finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
77	      ),
78	      ...finalState,
79	    });
80	  }
81	
82	  private async _playStep(
83	    gsap: GsapGlobal,
84	    veil: TransitionVeilRuntimePort,
85	    step: SceneTransitionStep,
86	  ): Promise<void> {
87	    const state = { progress: Helpers.clamp01(step.from) };
88	    veil.setRuntimeState({
89	      active: true,
90	      progress: state.progress,
91	    });
92	
93	    await new Promise<void>((resolve) => {
94	      gsap.to(state, {
95	        progress: Helpers.clamp01(step.to),
96	        duration: Math.max(0, step.duration),
97	        ease: this._resolveEase(step.ease),
98	        onUpdate: () => {
99	          veil.setRuntimeState({
100	            active: true,
101	            progress: state.progress,
102	          });
103	        },
104	        onComplete: () => resolve(),
105	      });
106	    });
107	  }
108	
109	  private _resolveEase(ease: TransitionEaseKey | undefined): string {
110	    if (ease === "easeInOutCubic") return "power2.inOut";
111	    return "none";
112	  }
113	}
